//! The code `rustorb-idl -brust` generates for `idl/RustMapping.idl`
//! (checked in as `generated/rust_mapping.rs`, regenerated by
//! `generate-rust.sh`): values, TypeCodes and anys, and calls through
//! the generated stubs and skeletons over TCP.

#[allow(dead_code)]
#[path = "generated/rust_mapping.rs"]
mod rust_mapping_idl;

use std::sync::{Arc, Mutex};

use rustorb_core::idl::{self, IdlType};
use rustorb_core::{
    Any, EndpointAddr, Fixed, LongDouble, ObjectRef, Orb, OrbOptions, Servant, SystemException,
    SystemExceptionKind, TCKind,
};

use rust_mapping_idl::rust_mapping::{self as m, *};

fn server_orb() -> Orb {
    Orb::with_options(OrbOptions {
        endpoints: vec![EndpointAddr {
            host: "127.0.0.1".into(),
            port: 0,
        }],
        ..OrbOptions::default()
    })
    .unwrap()
}

/// The same reference through another ORB, so that calls go over TCP.
fn remote(client: &Orb, server: &Orb, obj: &ObjectRef) -> ObjectRef {
    client
        .string_to_object(&server.object_to_string(Some(obj)).unwrap())
        .unwrap()
        .unwrap()
}

#[test]
fn names_and_constants() {
    assert_eq!(m::C_SHORT, -3);
    assert_eq!(m::C_MIN, i32::MIN);
    assert_eq!(m::C_ULONGLONG, 18_000_000_000_000_000_000);
    assert_eq!(m::C_DOUBLE, 0.25);
    assert_eq!(m::C_STRING, "abcd\n");
    assert_eq!(m::C_EXPR, (1 << 21) - 3);
    assert_eq!(m::MAX_COUNT, 5);
    assert_eq!(m::C_ENUM, Fruit::Banana);
    assert_eq!(m::c_fixed(), "12.5".parse::<Fixed>().unwrap());
    assert_eq!(m::base::BASE_CONST, 7);
    assert_eq!(m::inner::INNER_NAME, "inner");
    assert_eq!(m::REOPENED, 1);
    assert_eq!(rust_mapping_idl::GLOBAL_LIMIT, 10);
    assert_eq!(
        Fruit::VALUES,
        [Fruit::Apple, Fruit::Banana, Fruit::CherryPie]
    );
    assert_eq!(Fruit::from_u32(2), Some(Fruit::CherryPie));
    assert_eq!(Pair::REPOSITORY_ID, "IDL:rustorb.org/RustMapping/Pair:1.0");
    let _: m::outer::Mode = m::outer::Mode::Off;
    let _: m::Count2 = 3i32;
}

fn round_trip<T: IdlType>(v: &T::Borrowed) -> Result<T::Rust, SystemException> {
    let any = Any::insert::<T>(v)?;
    Ok(any.extract::<T>().expect("the same type"))
}

fn holder() -> Holder {
    Holder {
        numbers: [1, 2, 3],
        pairs: vec![Pair {
            first: 1,
            second: 2,
        }],
        cells: [[1, 2], [3, 4]],
        tag: "tag".into(),
        bounded: vec![1, 2, 3],
        extra: Any::from(5i32),
        target: None,
        price: "-123.45".parse().unwrap(),
        wide: "wïde".into(),
        letter: 'λ',
        ascii: 'a',
        data: vec![0, 255],
        names: vec!["α".into(), "β".into()],
        r#type: 9,
        self_: true,
        camel_case_name: "x".into(),
    }
}

#[test]
fn values_round_trip() {
    let h = holder();
    assert_eq!(round_trip::<Holder>(&h).unwrap(), h);

    let tree = Tree {
        label: "root".into(),
        children: vec![Tree {
            label: "leaf".into(),
            children: vec![],
        }],
    };
    assert_eq!(round_trip::<Tree>(&tree).unwrap(), tree);
    let node = Node::Branch(vec![Node::Leaf(1), Node::Branch(vec![])]);
    assert_eq!(round_trip::<Node>(&node).unwrap(), node);
    assert_eq!(
        Node::type_code().member_type(1).unwrap().kind(),
        TCKind::Sequence
    );

    for u in [ByBool::Yes(1), ByBool::No("n".into())] {
        assert_eq!(round_trip::<ByBool>(&u).unwrap(), u);
    }
    for u in [ByChar::A(1), ByChar::Bc('c', "c".into())] {
        assert_eq!(round_trip::<ByChar>(&u).unwrap(), u);
    }
    for u in [
        ByEnum::AppleCount(3),
        ByEnum::CherryName("pie".into()),
        ByEnum::Other(Fruit::Banana, true),
    ] {
        assert_eq!(round_trip::<ByEnum>(&u).unwrap(), u);
    }
    for u in [
        ByEnumImplicit::AppleCount(1),
        ByEnumImplicit::Default(Fruit::CherryPie),
    ] {
        assert_eq!(round_trip::<ByEnumImplicit>(&u).unwrap(), u);
    }
    assert_eq!(
        ByEnumImplicit::Default(Fruit::Banana).discriminator(),
        Fruit::Banana
    );
    let u = ByULongLong::Default(8);
    assert_eq!(round_trip::<ByULongLong>(&u).unwrap(), u);
    let u = WithArray::Cells([[1, 2], [3, 4]]);
    assert_eq!(round_trip::<WithArray>(&u).unwrap(), u);
    let o = Outer {
        nested: m::outer::Inner { v: 4 },
        switch_mode: m::outer::Mode::On,
    };
    assert_eq!(round_trip::<Outer>(&o).unwrap(), o);
    let e = Failure {
        code: 1,
        message: "m".into(),
        kind: Fruit::Apple,
    };
    assert_eq!(round_trip::<Failure>(&e).unwrap(), e);

    assert_eq!(m::C_QUAD, LongDouble::from_f64(0.5));
    let q = Quads {
        one: LongDouble::from_f64(-1.5),
        many: vec![LongDouble::from_f64(0.1), LongDouble::from_bits(1)],
        pair: [LongDouble::ZERO, LongDouble::from_f64(f64::INFINITY)],
    };
    assert_eq!(round_trip::<Quads>(&q).unwrap(), q);
    assert_eq!(
        Quads::type_code().member_type(0).unwrap().kind(),
        TCKind::LongDouble
    );
}

#[test]
fn checks_on_sending() {
    let kind = |e: SystemException| e.kind();
    // A discriminator that is not a label of the member.
    assert_eq!(
        kind(Any::insert::<ByChar>(&ByChar::Bc('a', "x".into())).unwrap_err()),
        Some(SystemExceptionKind::BAD_PARAM)
    );
    // The default member with a label's discriminator.
    assert_eq!(
        kind(Any::insert::<ByEnum>(&ByEnum::Other(Fruit::Apple, true)).unwrap_err()),
        Some(SystemExceptionKind::BAD_PARAM)
    );
    assert_eq!(
        kind(Any::insert::<ByULongLong>(&ByULongLong::Default(7)).unwrap_err()),
        Some(SystemExceptionKind::BAD_PARAM)
    );
    let mut h = holder();
    h.tag = "too long a tag".into();
    assert_eq!(
        kind(Any::insert::<Holder>(&h).unwrap_err()),
        Some(SystemExceptionKind::BAD_PARAM)
    );
    let mut h = holder();
    h.ascii = 'é';
    assert_eq!(
        kind(Any::insert::<Holder>(&h).unwrap_err()),
        Some(SystemExceptionKind::DATA_CONVERSION)
    );
}

#[test]
fn typecodes_and_anys() {
    let tc = Holder::type_code();
    assert_eq!(tc.kind(), TCKind::Struct);
    assert_eq!(tc.id().unwrap(), "IDL:rustorb.org/RustMapping/Holder:1.0");
    assert_eq!(tc.member_name(13).unwrap(), "type");
    assert_eq!(tc.member_type(4).unwrap().kind(), TCKind::Alias);

    let a = Any::insert::<m::alias::Octets>(&[1, 2]).unwrap();
    assert_eq!(a.typecode().kind(), TCKind::Alias);
    assert_eq!(a.typecode().name().unwrap(), "Octets");
    assert_eq!(a.extract::<m::alias::Octets>(), Some(vec![1, 2]));
    // An alias and its content are equivalent.
    assert_eq!(a.extract::<idl::Sequence<idl::Octet>>(), Some(vec![1, 2]));
    assert_eq!(a.extract::<Pair>(), None);

    let a = Any::insert::<Fruit>(&Fruit::CherryPie).unwrap();
    assert_eq!(a.extract::<Fruit>(), Some(Fruit::CherryPie));
    assert_eq!(a.typecode().member_name(2).unwrap(), "CHERRY_PIE");
    assert_eq!(m::alias::Money::type_code().kind(), TCKind::Alias);
}

#[test]
fn valuetypes() {
    // Circle arrives where Shape is declared. Each test that relies on it
    // registers, as the tests run in any order.
    rust_mapping_idl::register_value_types();
    let s = Shape::new(ShapeState {
        name: "s".into(),
        secret: 1,
    });
    let c = Circle::new(CircleState {
        base: ShapeState {
            name: "c".into(),
            secret: 2,
        },
        radius: 1.5,
    });
    let as_shape: Shape = c.clone().into();
    assert_eq!(as_shape.get().name, "c");
    assert!(Circle::try_from(as_shape.clone()).is_ok());
    assert!(Circle::try_from(s.clone()).is_err());
    s.with_mut(|st| st.secret = 3);
    assert_eq!(s.with(|st| st.secret), 3);

    // Sharing through a struct, and a derived type where the base is.
    let d = Drawing {
        main: Some(as_shape.clone()),
        others: vec![Some(as_shape.clone()), Some(s.clone()), None],
        count: Some(LongBox::new(4)),
    };
    let back = round_trip::<Drawing>(&d).unwrap();
    let main = back.main.unwrap();
    assert!(main.ptr_eq(back.others[0].as_ref().unwrap()));
    assert_eq!(Circle::try_from(main).unwrap().get().radius, 1.5);
    assert_eq!(back.others[1].as_ref().unwrap().get().secret, 3);
    assert!(back.others[2].is_none());
    assert_eq!(*back.count.unwrap(), 4);

    // Cycles.
    let a = Link::new(LinkState { id: 1, next: None });
    let b = Link::new(LinkState {
        id: 2,
        next: Some(a.clone()),
    });
    a.with_mut(|st| st.next = Some(b.clone()));
    let a2 = round_trip::<Link>(&Some(a.clone())).unwrap().unwrap();
    let b2 = a2.get().next.unwrap();
    assert_eq!(b2.get().id, 2);
    assert!(b2.get().next.unwrap().ptr_eq(&a2));
    for v in [a, a2] {
        v.with_mut(|st| st.next = None);
    }

    let pb = PairBox::new(Pair {
        first: 1,
        second: 2,
    });
    let back = round_trip::<PairBox>(&Some(pb.clone())).unwrap().unwrap();
    assert_eq!(back.first, 1);
    assert_eq!(PairBox::type_code().kind(), TCKind::ValueBox);
}

