#[derive(Default)]
struct DerivedImpl {
    label: Mutex<String>,
    notes: Mutex<Vec<String>>,
    this: Mutex<Option<ObjectRef>>,
}

impl BaseServant for DerivedImpl {
    fn id(&self) -> Result<i32, SystemException> {
        Ok(42)
    }

    fn label(&self) -> Result<String, SystemException> {
        Ok(self.label.lock().unwrap().clone())
    }

    fn set_label(&self, value: &str) -> Result<(), SystemException> {
        *self.label.lock().unwrap() = value.to_owned();
        Ok(())
    }

    fn base_op(&self) -> Result<(), m::base::BaseOpError> {
        Err(m::base::BaseError { why: "why".into() }.into())
    }
}

impl DerivedServant for DerivedImpl {
    fn derived_op(&self, a: i32, b: &mut i32) -> Result<(i32, i32), m::derived::DerivedOpError> {
        match a {
            0 => Err(Empty {}.into()),
            1 => Err(Failure {
                code: 7,
                message: "failed".into(),
                kind: Fruit::Banana,
            }
            .into()),
            2 => Err(SystemException::new(
                SystemExceptionKind::NO_PERMISSION,
                0,
                rustorb_core::CompletionStatus::No,
            )
            .into()),
            _ => {
                *b += a;
                Ok((a * 2, a * 3))
            }
        }
    }

    fn notify(&self, msg: &str) -> Result<(), SystemException> {
        self.notes.lock().unwrap().push(msg.to_owned());
        Ok(())
    }

    fn as_base(&self) -> Result<Option<Base>, SystemException> {
        Ok(self
            .this
            .lock()
            .unwrap()
            .clone()
            .map(Base::unchecked_narrow))
    }

    fn laters(&self) -> Result<m::base::LaterSeq, SystemException> {
        Ok(vec![None])
    }

    fn get_value(&self, r#match: &str, pair: &mut Pair) -> Result<String, SystemException> {
        pair.first += 1;
        Ok(format!("{match}!"))
    }

    fn take(
        &self,
        h: &Holder,
        p: &Pair,
        f: Fruit,
        o: &[u8],
        l: Option<&Later>,
        x: Option<&ObjectRef>,
        a: &Any,
        money: &Money,
        g: &Grid,
    ) -> Result<(), SystemException> {
        let ok = *h == holder()
            && p.first == 1
            && f == Fruit::Apple
            && o == [1, 2]
            && l.is_none()
            && x.is_some()
            && a.extract::<idl::Long>() == Some(5)
            && money.to_string() == "1.25"
            && g == &[[1, 2], [3, 4]];
        if ok {
            Ok(())
        } else {
            Err(SystemException::new(
                SystemExceptionKind::BAD_PARAM,
                0,
                rustorb_core::CompletionStatus::No,
            ))
        }
    }
}

#[test]
fn calls() {
    let server = server_orb();
    let root = server.root_poa().unwrap();
    root.the_poa_manager().activate().unwrap();
    let servant = DerivedImpl::default();
    let (_, local) = DerivedPoa(servant).activate(&root).unwrap();
    let client = Orb::with_options(OrbOptions::default()).unwrap();
    let obj = remote(&client, &server, local.object());

    let d = Derived::narrow(&obj).unwrap().unwrap();
    assert!(Other::narrow(&obj).unwrap().is_none());
    assert_eq!(d.id().unwrap(), 42);
    d.set_label("hello").unwrap();
    assert_eq!(d.label().unwrap(), "hello");

    let mut b = 10;
    assert_eq!(d.derived_op(5, &mut b).unwrap(), (10, 15));
    assert_eq!(b, 15);
    match d.derived_op(1, &mut b) {
        Err(m::derived::DerivedOpError::Failure(f)) => {
            assert_eq!(
                (f.code, f.message.as_str(), f.kind),
                (7, "failed", Fruit::Banana)
            )
        }
        r => panic!("{r:?}"),
    }
    let e = d.derived_op(0, &mut b).unwrap_err();
    assert!(matches!(e, m::derived::DerivedOpError::Empty(_)));
    assert_eq!(e.repository_id(), Empty::REPOSITORY_ID);
    match d.derived_op(2, &mut b) {
        Err(m::derived::DerivedOpError::System(e)) => {
            assert!(e.is(SystemExceptionKind::NO_PERMISSION))
        }
        r => panic!("{r:?}"),
    }
    match d.base_op() {
        Err(m::base::BaseOpError::BaseError(e)) => assert_eq!(e.why, "why"),
        r => panic!("{r:?}"),
    }

    let mut pair = Pair {
        first: 1,
        second: 2,
    };
    assert_eq!(d.get_value("m", &mut pair).unwrap(), "m!");
    assert_eq!(pair.first, 2);
    assert_eq!(d.laters().unwrap(), vec![None]);
    assert!(d.as_base().unwrap().is_none());

    d.take(
        &holder(),
        &Pair {
            first: 1,
            second: 0,
        },
        Fruit::Apple,
        &[1, 2],
        None,
        Some(&obj),
        &Any::from(5i32),
        &"1.25".parse().unwrap(),
        &[[1, 2], [3, 4]],
    )
    .unwrap();
    let e = d
        .take(
            &holder(),
            &Pair {
                first: 0,
                second: 0,
            },
            Fruit::Apple,
            &[1, 2],
            None,
            None,
            &Any::from(5i32),
            &"1.25".parse().unwrap(),
            &[[1, 2], [3, 4]],
        )
        .unwrap_err();
    assert!(e.is(SystemExceptionKind::BAD_PARAM));

    d.notify("one").unwrap();
    // The base type of the reference, and the widening conversion.
    let base: Base = d.clone().into();
    assert_eq!(base.id().unwrap(), 42);
    assert!(obj.is_a(Base::REPOSITORY_ID).unwrap());

    // An unknown operation.
    let e = obj.request("no_such_op").invoke().unwrap_err();
    assert!(
        e.as_system()
            .unwrap()
            .is(SystemExceptionKind::BAD_OPERATION)
    );
    drop(client);
    server.shutdown(true).unwrap();
}

#[derive(Debug)]
struct CanvasImpl;

impl CanvasServant for CanvasImpl {
    fn echo_shape(&self, s: Option<&Shape>) -> Result<Option<Shape>, SystemException> {
        Ok(s.cloned())
    }

    fn echo_drawing(&self, d: &Drawing) -> Result<Drawing, SystemException> {
        Ok(d.clone())
    }

    fn echo_box(&self, b: Option<&LongBox>) -> Result<Option<LongBox>, SystemException> {
        Ok(b.cloned())
    }

    fn echo_tagged(&self, t: Option<&Tagged>) -> Result<Option<Tagged>, SystemException> {
        Ok(t.cloned())
    }

    fn echo_gauge(&self, g: Option<&Gauge>) -> Result<Option<Gauge>, SystemException> {
        Ok(g.cloned())
    }

    fn read_meter(&self, m: Option<&Meter>) -> Result<i32, SystemException> {
        m.unwrap().reading()
    }
}

/// Tagged on the wire: the tag, then the text.
impl idl::CustomMarshal for TaggedState {
    fn marshal(&self, os: &mut idl::DataOutputStream<'_, '_>) -> idl::Sys<()> {
        os.write::<idl::Long>(&self.tag)?;
        os.write::<idl::String>(&self.text)
    }

    fn unmarshal(&mut self, is: &mut idl::DataInputStream<'_, '_>) -> idl::Sys<()> {
        self.tag = is.read::<idl::Long>()?;
        self.text = is.read::<idl::String>()?;
        Ok(())
    }
}

impl GaugeOperations for GaugeState {
    fn reading(&mut self) -> Result<i32, SystemException> {
        Ok(self.level)
    }

    fn scaled(&mut self, by: i32) -> Result<i32, SystemException> {
        Ok(self.level * by)
    }
}

#[test]
fn custom_and_behaviour() {
    rust_mapping_idl::register_value_types();
    let t = Tagged::new(TaggedState {
        tag: 7,
        text: "seven".into(),
    });
    assert_eq!(Tagged::type_code().type_modifier().unwrap(), 1);

    // In an any, the core's instance holds the items unmarshal read.
    let any = Any::insert::<Tagged>(&Some(t)).unwrap();
    let rustorb_core::Value::Valuetype(Some(r)) = any.value() else {
        panic!("a value: {any:?}");
    };
    let items: Vec<_> = r
        .members()
        .into_iter()
        .map(|i| match i {
            rustorb_core::Value::Any(a) => a.value().clone(),
            other => panic!("an item: {other:?}"),
        })
        .collect();
    assert_eq!(
        items,
        [
            rustorb_core::Value::Long(7),
            rustorb_core::Value::String("seven".into())
        ]
    );
    let back = any.extract::<Tagged>().unwrap().unwrap();
    assert_eq!(back.get().tag, 7);
    assert_eq!(back.get().text, "seven");

    // The any as received: read by the core, then extracted.
    let mut enc = rustorb_core::cdr::Encoder::new(
        rustorb_core::cdr::ByteOrder::Little,
        rustorb_core::cdr::Encoding::Giop1_2,
    );
    rustorb_core::OutStream::standalone(&mut enc)
        .write_any(&any)
        .unwrap();
    let bytes = enc.into_bytes();
    let dec = rustorb_core::cdr::Decoder::new(
        &bytes,
        rustorb_core::cdr::ByteOrder::Little,
        rustorb_core::cdr::Encoding::Giop1_2,
    );
    let received = rustorb_core::InStream::standalone(dec, None)
        .read_any()
        .unwrap();
    let back = received.extract::<Tagged>().unwrap().unwrap();
    assert_eq!(back.get().text, "seven");

    let g = Gauge::new(GaugeState { level: 4 });
    assert_eq!(g.scaled(3).unwrap(), 12);
    assert_eq!(MeterServant::reading(&g).unwrap(), 4);
    let back = round_trip::<Gauge>(&Some(g)).unwrap().unwrap();
    assert_eq!(back.scaled(2).unwrap(), 8);
}

#[test]
fn valuetype_calls() {
    rust_mapping_idl::register_value_types();
    let server = server_orb();
    let root = server.root_poa().unwrap();
    root.the_poa_manager().activate().unwrap();
    let servant: Arc<dyn Servant> = Arc::new(CanvasPoa(CanvasImpl));
    let id = root.activate_object(servant).unwrap();
    let client = Orb::with_options(OrbOptions::default()).unwrap();
    let obj = remote(&client, &server, &root.id_to_reference(&id).unwrap());
    let canvas = Canvas::unchecked_narrow(obj);

    let c = Circle::new(CircleState {
        base: ShapeState {
            name: "c".into(),
            secret: 2,
        },
        radius: 2.5,
    });
    let back = canvas.echo_shape(Some(&c.clone().into())).unwrap().unwrap();
    let back = Circle::try_from(back).unwrap();
    assert_eq!(back.get().radius, 2.5);
    assert_eq!(back.get().base.secret, 2);
    assert!(canvas.echo_shape(None).unwrap().is_none());

    let shape: Shape = c.into();
    let d = Drawing {
        main: Some(shape.clone()),
        others: vec![Some(shape)],
        count: None,
    };
    let back = canvas.echo_drawing(&d).unwrap();
    assert!(
        back.main
            .as_ref()
            .unwrap()
            .ptr_eq(back.others[0].as_ref().unwrap())
    );
    assert_eq!(
        *canvas.echo_box(Some(&LongBox::new(9))).unwrap().unwrap(),
        9
    );

    let t = Tagged::new(TaggedState {
        tag: 1,
        text: "one".into(),
    });
    let back = canvas.echo_tagged(Some(&t)).unwrap().unwrap();
    assert_eq!((back.get().tag, back.get().text), (1, "one".to_owned()));
    let g = Gauge::new(GaugeState { level: 5 });
    assert_eq!(
        canvas
            .echo_gauge(Some(&g))
            .unwrap()
            .unwrap()
            .scaled(2)
            .unwrap(),
        10
    );
    // The Gauge, activated as a servant of Meter, called back by the
    // server.
    let client_root = client.root_poa().unwrap();
    client_root.the_poa_manager().activate().unwrap();
    let (_, meter) = MeterPoa(g).activate(&client_root).unwrap();
    assert_eq!(canvas.read_meter(Some(&meter)).unwrap(), 5);
    drop(client);
    server.shutdown(true).unwrap();
}

/// Checks at compile time that a future can go to `tokio::spawn`.
fn assert_send<T: Send>(t: T) -> T {
    t
}

#[test]
fn async_calls() {
    rust_mapping_idl::register_value_types();
    let server = server_orb();
    let root = server.root_poa().unwrap();
    root.the_poa_manager().activate().unwrap();
    let (_, local) = DerivedPoa(DerivedImpl::default()).activate(&root).unwrap();
    let canvas_id = root
        .activate_object(Arc::new(CanvasPoa(CanvasImpl)))
        .unwrap();
    let canvas_ref = root.id_to_reference(&canvas_id).unwrap();
    let client = Orb::with_options(OrbOptions::default()).unwrap();
    let obj = remote(&client, &server, local.object());
    let d = Derived::unchecked_narrow(obj.clone());
    let canvas = Canvas::unchecked_narrow(remote(&client, &server, &canvas_ref));

    let rt = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(2)
        .build()
        .unwrap();
    rt.block_on(async {
        // Attributes, inout, and the error types of the sync stubs.
        assert_eq!(assert_send(d.id_async()).await.unwrap(), 42);
        d.set_label_async("async").await.unwrap();
        assert_eq!(d.label_async().await.unwrap(), "async");
        let mut b = 10;
        assert_eq!(
            assert_send(d.derived_op_async(5, &mut b)).await.unwrap(),
            (10, 15)
        );
        assert_eq!(b, 15);
        match d.derived_op_async(1, &mut b).await {
            Err(m::derived::DerivedOpError::Failure(f)) => assert_eq!(f.code, 7),
            r => panic!("{r:?}"),
        }
        match d.derived_op_async(2, &mut b).await {
            Err(m::derived::DerivedOpError::System(e)) => {
                assert!(e.is(SystemExceptionKind::NO_PERMISSION))
            }
            r => panic!("{r:?}"),
        }

        // Borrowed arguments of every kind: structs, sequences, references,
        // anys, fixed, arrays.
        let holder = holder();
        let any = Any::from(5i32);
        let fixed = "1.25".parse().unwrap();
        let pair = Pair {
            first: 1,
            second: 0,
        };
        assert_send(d.take_async(
            &holder,
            &pair,
            Fruit::Apple,
            &[1, 2],
            None,
            Some(&obj),
            &any,
            &fixed,
            &[[1, 2], [3, 4]],
        ))
        .await
        .unwrap();
        assert_send(d.notify_async("one")).await.unwrap();

        // Valuetypes: sharing is kept as with the sync stubs.
        let c = Circle::new(CircleState {
            base: ShapeState {
                name: "c".into(),
                secret: 2,
            },
            radius: 2.5,
        });
        let shape: Shape = c.into();
        let drawing = Drawing {
            main: Some(shape.clone()),
            others: vec![Some(shape)],
            count: None,
        };
        let back = assert_send(canvas.echo_drawing_async(&drawing))
            .await
            .unwrap();
        assert!(
            back.main
                .as_ref()
                .unwrap()
                .ptr_eq(back.others[0].as_ref().unwrap())
        );

        // Calls spawned on the runtime's workers, at the same time.
        let calls: Vec<_> = (0..8)
            .map(|_| {
                let d = d.clone();
                tokio::spawn(async move { d.id_async().await })
            })
            .collect();
        for c in calls {
            assert_eq!(c.await.unwrap().unwrap(), 42);
        }
    });
    drop(client);
    server.shutdown(true).unwrap();
}

impl NoteOperations for NoteState {
    fn label_of(&mut self) -> idl::Sys<String> {
        Ok(self.text.clone())
    }

    fn rank(&mut self) -> idl::Sys<i32> {
        Ok(self.level)
    }

    fn set_rank(&mut self, value: i32) -> idl::Sys<()> {
        self.level = value;
        Ok(())
    }

    fn retitle(&mut self, title: &mut String) -> Result<(), titled::RetitleError> {
        if title.is_empty() {
            return Err(Failure {
                code: 1,
                message: "empty".into(),
                kind: Fruit::Apple,
            }
            .into());
        }
        std::mem::swap(&mut self.text, title);
        Ok(())
    }
}

struct BookImpl {
    title: Mutex<String>,
}

impl LabeledServant for BookImpl {
    fn label_of(&self) -> idl::Sys<String> {
        Ok(self.title.lock().unwrap().clone())
    }
}

impl TitledServant for BookImpl {
    fn rank(&self) -> idl::Sys<i32> {
        Ok(1)
    }

    fn set_rank(&self, _value: i32) -> idl::Sys<()> {
        Err(SystemException::new(
            SystemExceptionKind::NO_PERMISSION,
            0,
            rustorb_core::CompletionStatus::No,
        ))
    }

    fn retitle(&self, title: &mut String) -> Result<(), titled::RetitleError> {
        std::mem::swap(&mut *self.title.lock().unwrap(), title);
        Ok(())
    }
}

impl BookServant for BookImpl {
    fn pages(&self) -> idl::Sys<i32> {
        Ok(self.title.lock().unwrap().len() as i32 * 10)
    }
}

struct ShelfImpl {
    poa: rustorb_core::Poa,
}

impl ShelfServant for ShelfImpl {
    fn echo_titled(&self, t: Option<&Titled>) -> idl::Sys<Option<Titled>> {
        Ok(t.cloned())
    }

    fn echo_titled_pair(&self, p: &TitledPair) -> idl::Sys<TitledPair> {
        Ok(p.clone())
    }

    fn label(&self, l: Option<&Labeled>) -> idl::Sys<String> {
        l.ok_or_else(idl::bad_param)?.label_of()
    }

    fn make_book(&self, title: &str) -> idl::Sys<Option<Book>> {
        let book = BookPoa(BookImpl {
            title: Mutex::new(title.into()),
        });
        Ok(Some(book.activate(&self.poa).unwrap().1))
    }
}

#[test]
fn abstract_interfaces() {
    rust_mapping_idl::register_value_types();
    assert_eq!(Titled::type_code().kind(), TCKind::AbstractInterface);
    assert_eq!(Titled::type_code().id().unwrap(), Titled::REPOSITORY_ID);

    // A value, with the operations in this process.
    let note = Note::new(NoteState {
        text: "draft".into(),
        level: 3,
    });
    let t: Titled = note.clone().into();
    assert!(t.object().is_none());
    assert!(t.value().unwrap().ptr_eq(note.handle()));
    assert_eq!(t.label_of().unwrap(), "draft");
    t.set_rank(4).unwrap();
    assert_eq!(note.get().level, 4);
    let mut title = "final".to_owned();
    t.retitle(&mut title).unwrap();
    assert_eq!(
        (title.as_str(), t.label_of().unwrap().as_str()),
        ("draft", "final")
    );
    let mut empty = String::new();
    assert!(matches!(
        t.retitle(&mut empty),
        Err(titled::RetitleError::Failure(_))
    ));
    // The base abstract interface.
    let l: Labeled = t.clone().into();
    assert_eq!(l.label_of().unwrap(), "final");
    assert!(Titled::from_value(note.handle()).is_some());
    assert!(Labeled::from_value(note.handle()).is_some());
    let other = Shape::new(ShapeState::default());
    assert!(Titled::from_value(other.handle()).is_none());

    // Marshaled: FALSE and the value, sharing kept; TRUE and nil for none.
    let back = round_trip::<Titled>(&Some(t.clone())).unwrap().unwrap();
    assert_eq!(back.label_of().unwrap(), "final");
    assert!(round_trip::<Titled>(&None).unwrap().is_none());
    let p = TitledPair {
        first: Some(t.clone()),
        second: Some(l),
    };
    let back = round_trip::<TitledPair>(&p).unwrap();
    let (Some(Titled::Value(a)), Some(Labeled::Value(b))) = (&back.first, &back.second) else {
        panic!("values: {back:?}");
    };
    assert!(a.handle().ptr_eq(b.handle()));
    // A value of a type that does not support it.
    let mut enc = rustorb_core::cdr::Encoder::new(
        rustorb_core::cdr::ByteOrder::Little,
        rustorb_core::cdr::CdrVersion::Giop1_2,
    );
    {
        let mut out = rustorb_core::OutStream::standalone(&mut enc);
        idl::write_abstract_value(other.handle(), &mut out).unwrap();
    }
    let bytes = enc.into_bytes();
    let dec = rustorb_core::cdr::Decoder::new(
        &bytes,
        rustorb_core::cdr::ByteOrder::Little,
        rustorb_core::cdr::CdrVersion::Giop1_2,
    );
    let mut input = rustorb_core::InStream::standalone(dec, None);
    let e = <Titled as IdlType>::read(&mut input).unwrap_err();
    assert!(e.is(SystemExceptionKind::MARSHAL));

    // In an any.
    let any = Any::insert::<Titled>(&Some(t)).unwrap();
    assert_eq!(any.typecode().kind(), TCKind::AbstractInterface);
    let back = any.extract::<Titled>().unwrap().unwrap();
    assert_eq!(back.label_of().unwrap(), "final");
}

#[test]
fn abstract_interface_calls() {
    rust_mapping_idl::register_value_types();
    let server = server_orb();
    let root = server.root_poa().unwrap();
    root.the_poa_manager().activate().unwrap();
    let servant: Arc<dyn Servant> = Arc::new(ShelfPoa(ShelfImpl { poa: root.clone() }));
    let id = root.activate_object(servant).unwrap();
    let client = Orb::with_options(OrbOptions::default()).unwrap();
    let obj = remote(&client, &server, &root.id_to_reference(&id).unwrap());
    let shelf = Shelf::unchecked_narrow(obj);

    // An object: the operations are calls.
    let book = shelf.make_book("dune").unwrap().unwrap();
    assert_eq!(book.pages().unwrap(), 40);
    let t: Titled = book.clone().into();
    assert_eq!(t.label_of().unwrap(), "dune");
    assert!(Titled::narrow(book.object()).unwrap().is_some());
    let back = shelf.echo_titled(Some(&t)).unwrap().unwrap();
    assert!(back.object().unwrap().is_equivalent(book.object()));
    assert_eq!(back.label_of().unwrap(), "dune");
    let mut title = "arrakis".to_owned();
    back.retitle(&mut title).unwrap();
    assert_eq!(title, "dune");
    assert!(
        back.set_rank(2)
            .unwrap_err()
            .is(SystemExceptionKind::NO_PERMISSION)
    );
    assert_eq!(shelf.label(Some(&t.into())).unwrap(), "arrakis");

    // A value: sent by value, and its operations run on the server.
    let note: Titled = Note::new(NoteState {
        text: "memo".into(),
        level: 1,
    })
    .into();
    assert_eq!(shelf.label(Some(&note.clone().into())).unwrap(), "memo");
    let back = shelf.echo_titled(Some(&note)).unwrap().unwrap();
    assert!(back.object().is_none());
    assert_eq!(back.rank().unwrap(), 1);
    let p = shelf
        .echo_titled_pair(&TitledPair {
            first: Some(note.clone()),
            second: Some(note.into()),
        })
        .unwrap();
    assert!(
        p.first
            .unwrap()
            .value()
            .unwrap()
            .ptr_eq(p.second.unwrap().value().unwrap())
    );
    assert!(shelf.echo_titled(None).unwrap().is_none());

    // The async version.
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();
    assert_eq!(rt.block_on(t_label(&back_ref(&shelf))), "dune-async");
    drop(client);
    server.shutdown(true).unwrap();
}

fn back_ref(shelf: &Shelf) -> Titled {
    shelf.make_book("dune-async").unwrap().unwrap().into()
}

async fn t_label(t: &Titled) -> String {
    t.label_of_async().await.unwrap()
}

struct Counter {
    fired: Mutex<Vec<i32>>,
}

impl Hook for Counter {
    fn fire(&self, n: i32, next: Option<&Arc<dyn Hook>>) -> idl::Sys<i32> {
        self.fired.lock().unwrap().push(n);
        match next {
            Some(h) => Ok(n + h.fire(n + 1, None)?),
            None => Ok(n),
        }
    }
}

impl LoudHook for Counter {
    fn shout(&self, s: &str) -> Result<(), loud_hook::ShoutError> {
        if s.is_empty() {
            return Err(Failure {
                code: 2,
                message: "quiet".into(),
                kind: Fruit::Apple,
            }
            .into());
        }
        Ok(())
    }

    fn last(&self) -> idl::Sys<Pair> {
        Ok(Pair::default())
    }
}

impl BellOperations for BellState {
    fn fire(&mut self, n: i32, _next: Option<&Arc<dyn Hook>>) -> idl::Sys<i32> {
        self.rings += 1;
        Ok(n * 100)
    }
}

#[test]
fn local_interfaces() {
    assert_eq!(hook::REPOSITORY_ID, "IDL:rustorb.org/RustMapping/Hook:1.0");
    let a = Arc::new(Counter {
        fired: Mutex::new(Vec::new()),
    });
    let b: Arc<dyn Hook> = Arc::new(Counter {
        fired: Mutex::new(Vec::new()),
    });
    assert_eq!(a.fire(1, Some(&b)).unwrap(), 3);
    assert_eq!(*a.fired.lock().unwrap(), [1]);
    let loud: Arc<dyn LoudHook> = a.clone();
    assert!(matches!(
        loud.shout(""),
        Err(loud_hook::ShoutError::Failure(_))
    ));
    assert_eq!(loud.fire(5, None).unwrap(), 5);
    // A valuetype that supports a local interface.
    let bell = Bell::new(BellState { rings: 0 });
    let h: Arc<dyn Hook> = Arc::new(bell.clone());
    assert_eq!(a.fire(1, Some(&h)).unwrap(), 201);
    assert_eq!(bell.get().rings, 1);
}
